  // ---------- combos ----------
  // 连携发动条件（硬依赖）。元素可以是单个、数组、any/anyArts/otherArts；破防层数读 S.breach；异常条件看种类；目标前提（targetRequires）按结构判定。
  const PHYS=['knockup','knockdown','crush','armorBreak']; const ARMOR_BREAK_SECONDS=10; /* 碎甲物理易伤时长：官方未给，暂按 10 s（verification-needed 34） */
