  // ---------- actions ----------
  function rankOf(mb,k){ return mb.member.skillRanks?.[k]??12; }
  // 条件伤害段：按标签判定（冻结/非冻结、终结技期间）；其余条件段（强化/追加/提前降下/集束打击/诀明等）默认不执行并记 note（技能状态机缺口，sim-design §5）
