    function procProb(mb,name){ const p=mb.mech?.procs?.[name]; if(!p) return 0; let pr=num(p.base)??0; if(p.perInt){ const i=mb.stats?.abilities?.int??0; pr+=Math.min(p.perInt.max??1,Math.floor(i/(p.perInt.per||10))*(p.perInt.add||0)); } if(p.stacksEffect){ const b=S.buffs.find(b=>b.cand.effect.id===p.stacksEffect&&b.ownerIdx===mb.idx&&b.until>=S.t-EPS); pr+=(b?.stacks||0)*(p.perStack||0); } if(p.mul) pr*=p.mul; return Math.min(1,Math.max(0,pr)); }
